import React, { useState, useEffect, useRef } from 'react';
import { Send, TerminalSquare, RefreshCw, Smartphone, Monitor } from 'lucide-react';
import { Message, LogEntry, AppMode } from './types';
import { sendMessageToGemini } from './services/geminiService';
import Terminal from './components/Terminal';
import ChatBubble from './components/ChatBubble';

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [mode, setMode] = useState<AppMode>(AppMode.HYBRID);

  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Helper to add logs
  const addLog = (level: LogEntry['level'], message: string) => {
    const now = new Date();
    const timestamp = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}:${now.getSeconds().toString().padStart(2, '0')}.${now.getMilliseconds().toString().padStart(3, '0')}`;

    setLogs(prev => [...prev, {
      id: Math.random().toString(36).substr(2, 9),
      timestamp,
      level,
      message
    }]);
  };

  // Scroll to bottom of chat
  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // Initial System Boot
  useEffect(() => {
    const bootSequence = async () => {
      addLog('INFO', 'Initializing Neural Interface...');
      await new Promise(r => setTimeout(r, 200));
      addLog('DEBUG', 'Loading chat_contexts.json...');
      await new Promise(r => setTimeout(r, 150));
      addLog('INFO', 'Successfully loaded user profile: Guest');
      await new Promise(r => setTimeout(r, 150));
      addLog('INFO', 'Gemini API client ready.');
      addLog('INFO', 'Sentiment analysis engine: ONLINE');
      setMessages([{
        id: 'init',
        role: 'model',
        content: "System online. I'm ready to chat.",
        timestamp: new Date()
      }]);
    };
    bootSequence();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsgText = input;
    setInput('');
    setIsLoading(true);

    const newUserMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: userMsgText,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, newUserMsg]);

    // Simulate extensive system processing like in the screenshot
    try {
      addLog('INFO', `Received message from user: "${userMsgText.substring(0, 20)}..."`);
      await new Promise(r => setTimeout(r, 100));
      addLog('DEBUG', `Analyzing sentiment...`);
      await new Promise(r => setTimeout(r, 300));
      addLog('INFO', `Sentiment detected: Neutral/Positive (Confidence: 0.98)`);
      addLog('DEBUG', `Constructing payload for Gemini-2.5-Flash`);
      addLog('API', `POST https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent`);

      const responseText = await sendMessageToGemini(messages, userMsgText);

      addLog('API', `Response received: 200 OK`);
      addLog('INFO', `Token usage: ${Math.floor(Math.random() * 50) + 10} tokens`);
      addLog('DEBUG', `Processing markdown...`);

      const newBotMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: responseText,
        timestamp: new Date()
      };

      setMessages(prev => [...prev, newBotMsg]);
      addLog('INFO', `Message delivered to client.`);

    } catch (error) {
      addLog('ERROR', `Failed to generate response: ${error instanceof Error ? error.message : 'Unknown error'}`);
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'model',
        content: "Connection error. Please check the system logs.",
        timestamp: new Date()
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  const toggleMode = () => {
    if (mode === AppMode.CHAT) setMode(AppMode.HYBRID);
    else if (mode === AppMode.HYBRID) setMode(AppMode.TERMINAL);
    else setMode(AppMode.CHAT);
  };

  return (
    <div className="flex h-screen w-full bg-slate-900 items-center justify-center relative overflow-hidden">

      {/* Background Decor */}
      <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_top,_var(--tw-gradient-stops))] from-slate-800 via-slate-900 to-black pointer-events-none"></div>

      {/* Main Container - Mobile Frame */}
      <div className={`relative w-full h-full md:h-[90vh] md:w-[450px] bg-slate-50 md:rounded-[3rem] shadow-2xl overflow-hidden flex flex-col transition-all duration-500 border-4 border-slate-800`}>

        {/* Dynamic Status Bar */}
        <div className="h-12 bg-slate-100 flex items-center justify-between px-6 border-b border-gray-200 z-20">
            <span className="font-semibold text-slate-700 text-sm">15:31</span>
            <div className="flex items-center gap-1">
                <div className="w-4 h-4 rounded-full bg-black/10"></div>
                <div className="w-10 h-3 bg-black/10 rounded-full"></div>
            </div>
        </div>

        {/* Content Area */}
        <div className="flex-1 relative flex flex-col min-h-0 bg-[#F5F5F5]">

          {/* Layer 1: Chat Interface */}
          <div className={`flex-1 overflow-y-auto p-4 transition-all duration-300 ${mode === AppMode.TERMINAL ? 'opacity-0 pointer-events-none' : 'opacity-100'}`}>
             <div className="flex flex-col min-h-full justify-end">
                {messages.length === 0 && (
                  <div className="text-center text-gray-400 my-auto text-sm">
                    <p>Start conversation with neural core...</p>
                  </div>
                )}
                {messages.map((msg) => (
                  <ChatBubble key={msg.id} message={msg} />
                ))}
                {isLoading && (
                  <div className="flex items-center gap-2 text-gray-400 text-xs ml-4 mb-4">
                    <RefreshCw className="animate-spin w-3 h-3" />
                    <span>Neural core processing...</span>
                  </div>
                )}
                <div ref={messagesEndRef} />
             </div>
          </div>

          {/* Layer 2: Terminal Overlay (The "Hybrid" Mode from screenshot) */}
          <div className={`absolute inset-x-0 top-0 transition-all duration-500 ease-in-out z-10 
            ${mode === AppMode.HYBRID ? 'h-[40%] border-b border-green-900/50' : mode === AppMode.TERMINAL ? 'h-full' : 'h-0 opacity-0'}
          `}>
             <Terminal logs={logs} isOpen={true} className="h-full w-full" />
          </div>

        </div>

        {/* Input Area */}
        <div className="p-4 bg-white border-t border-gray-100 z-20">
          <form 
            onSubmit={(e) => { e.preventDefault(); handleSend(); }}
            className="flex items-center gap-3"
          >
            <button
              type="button"
              onClick={toggleMode}
              className="p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-full transition-colors"
              title="Toggle Debug Layer"
            >
              {mode === AppMode.CHAT ? <Smartphone size={20} /> : 
               mode === AppMode.HYBRID ? <TerminalSquare size={20} /> :
               <Monitor size={20} />}
            </button>

            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="Type message..."
              className="flex-1 bg-gray-100 text-gray-800 rounded-full px-4 py-2 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:bg-white transition-all"
            />

            <button
              type="submit"
              disabled={isLoading || !input.trim()}
              className={`p-2 rounded-full transition-all ${
                isLoading || !input.trim() 
                ? 'bg-gray-200 text-gray-400' 
                : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-md transform active:scale-95'
              }`}
            >
              <Send size={20} />
            </button>
          </form>
        </div>

      </div>

      {/* Desktop Helper Text */}
      <div className="hidden md:block absolute right-10 bottom-10 text-slate-500 text-sm max-w-xs text-right">
        <h3 className="font-bold text-slate-300 mb-2">Controls</h3>
        <p>Click the <TerminalSquare className="inline w-4 h-4 mx-1" /> icon to toggle the system logs overlay.</p>
        <p className="mt-2 text-xs opacity-50">Mimics real-time backend processing visualization.</p>
      </div>

    </div>
  );
};

export default App;

