interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  currentUserNickname: string;
  currentUserAvatar: string;
  currentBotNickname: string;
  currentBotAvatar: string;
  onSave: (userNickname: string, userAvatar: string, botNickname: string, botAvatar: string) => void;
}

const SettingsModal: React.FC<SettingsModalProps> = ({
  isOpen,
  onClose,
  currentUserNickname,
  currentUserAvatar,
  currentBotNickname,
  currentBotAvatar,
  onSave,
}) => {
  const [activeTab, setActiveTab] = useState<'user' | 'bot'>('user');

  // User State
  const [userNickname, setUserNickname] = useState(currentUserNickname);
  const [userAvatar, setUserAvatar] = useState(currentUserAvatar);

  // Bot State
  const [botNickname, setBotNickname] = useState(currentBotNickname);
  const [botAvatar, setBotAvatar] = useState(currentBotAvatar);

  // Reset state when modal opens
  useEffect(() => {
    if (isOpen) {
      setUserNickname(currentUserNickname);
      setUserAvatar(currentUserAvatar);
      setBotNickname(currentBotNickname);
      setBotAvatar(currentBotAvatar);
      setActiveTab('user');
    }
  }, [isOpen, currentUserNickname, currentUserAvatar, currentBotNickname, currentBotAvatar]);

  const handleRandomizeAvatar = (type: 'user' | 'bot') => {
    const randomSeed = Math.random().toString(36).substring(7);
    if (type === 'user') {
      setUserAvatar(`https://api.dicebear.com/9.x/avataaars/svg?seed=${randomSeed}`);
    } else {
      setBotAvatar(`https://api.dicebear.com/9.x/bottts-neutral/svg?seed=${randomSeed}`);
    }
  };

  const handleSave = () => {
    onSave(userNickname, userAvatar, botNickname, botAvatar);
    onClose();
  };

  if (!isOpen) return null;

  const isUserTab = activeTab === 'user';
  const currentAvatar = isUserTab ? userAvatar : botAvatar;
  const setAvatar = isUserTab ? setUserAvatar : setBotAvatar;
  const currentNickname = isUserTab ? userNickname : botNickname;
  const setNickname = isUserTab ? setUserNickname : setBotNickname;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm">
