const CACHE_NAME = 'gemini-chat-v1';
const urlsToCache = [
  '/',
  '/index.html'
];

self.addEventListener('install', event => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then(cache => {
        return cache.addAll(urlsToCache);
      })
  );
});

self.addEventListener('fetch', event => {
  event.respondWith(
    caches.match(event.request)
      .then(response => {
        // Cache hit - return response
        if (response) {
          return response;
        }
        return fetch(event.request);
      })
  );
});

self.addEventListener('activate', event => {
  const cacheWhitelist = [CACHE_NAME];
  event.waitUntil(
    caches.keys().then(cacheNames => {
      return Promise.all(
        cacheNames.map(cacheName => {
          if (cacheWhitelist.indexOf(cacheName) === -1) {
            return caches.delete(cacheName);
          }
        })
      );
    })
  );
});

import { GoogleGenAI } from "@google/genai";
import { Message } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Type definitions for Chrome's experimental built-in AI
declare global {
  interface Window {
    ai?: {
      languageModel?: {
        capabilities: () => Promise<{ available: 'readily' | 'after-download' | 'no' }>;
        create: (options?: any) => Promise<{
          prompt: (input: string) => Promise<string>;
          promptStreaming?: (input: string) => AsyncIterable<string>;
        }>;
      };
    };
  }
}

/**
 * Generates a simulated response when the app is offline and no local model is found.
 */
const getOfflineResponse = (text: string): string => {
  const lower = text.toLowerCase();
  const prefix = "[Offline Auto-Reply] ";

  // Simple rule-based responses
  if (lower.match(/\b(hi|hello|hey|greetings|yo)\b/)) {
    return prefix + "Hello! We are currently offline. I can't reach the cloud, but I'm here!";
  }
  if (lower.includes("time")) {
    return prefix + `Local time: ${new Date().toLocaleTimeString()}.`;
  }
  if (lower.includes("date")) {
    return prefix + `Today's date: ${new Date().toLocaleDateString()}.`;
  }

  const defaults = [
    "I'm currently offline and cannot reach the Gemini server.",
    "No internet connection detected. This is an automated fallback message.",
    "Please check your internet connection to chat with the real Gemini.",
    "I'm in offline mode. I can't think deeply right now!"
  ];

  return prefix + defaults[Math.floor(Math.random() * defaults.length)];
};

/**
 * Tries to generate a response using Chrome's built-in local AI (Gemini Nano).
 */
const generateLocalResponse = async (text: string): Promise<string | null> => {
  try {
    if (!window.ai?.languageModel) {
      return null;
    }

    const capabilities = await window.ai.languageModel.capabilities();
    if (capabilities.available === 'no') {
      return null;
    }

    // Create a session with the local model
    const session = await window.ai.languageModel.create({
      systemPrompt: "You are a helpful assistant in an offline chat application. Keep answers concise."
    });

    const result = await session.prompt(text);
    return `[Local AI] ${result}`;
  } catch (error) {
    console.warn("Failed to use local AI:", error);
    return null;
  }
};

export const sendMessageToGemini = async (
  history: Message[], 
  newMessage: string
): Promise<string> => {
  // 1. Check if browser explicitly reports offline
  if (!navigator.onLine) {
    console.log("App is offline.");

    // Try to use Chrome's built-in Local AI first
    const localResponse = await generateLocalResponse(newMessage);
    if (localResponse) {
      return localResponse;
    }

    // Fallback to simulation
    await new Promise(resolve => setTimeout(resolve, 800));
    return getOfflineResponse(newMessage);
  }

  try {
    const chatHistory = history.slice(-15).map(msg => ({
      role: msg.role,
      parts: [{ text: msg.content }],
    }));

    const chat = ai.chats.create({
      model: 'gemini-2.5-flash',
      history: chatHistory,
      config: {
        systemInstruction: "You are a friendly friend chatting on a messaging app. Keep your responses casual, helpful, and concise. Use emojis occasionally.",
      },
    });

    const result = await chat.sendMessage({ message: newMessage });
    return result.text || "";
  } catch (error) {
    console.warn("Gemini API Error:", error);

    // 2. API Failed (timeout/server error) -> Try local AI, then simulation
    const localResponse = await generateLocalResponse(newMessage);
    if (localResponse) {
      return localResponse;
    }

    await new Promise(resolve => setTimeout(resolve, 500)); 
    return getOfflineResponse(newMessage);
  }
};

