import React, { useState, useEffect, useRef } from 'react';
import { Message, AppSettings } from './types';
import { sendMessageToAI } from './services/geminiService';
import ChatBubble from './components/ChatBubble';
import SettingsModal from './components/SettingsModal';
import { 
  Smile, 
  Folder, 
  Paperclip,
  MoreHorizontal
} from 'lucide-react';

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  // Consolidated Settings State
  const [settings, setSettings] = useState<AppSettings>({
    userAvatar: 'https://api.dicebear.com/9.x/avataaars/svg?seed=Felix',
    botNickname: 'Gemini Assistant',
    botAvatar: 'https://api.dicebear.com/9.x/bottts-neutral/svg?seed=Gemini',
    aiProvider: 'gemini',
    ollamaModel: 'qwen2.5:7b',
    ollamaBaseUrl: 'http://localhost:11434'
  });

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'auto' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // Initial Message
  useEffect(() => {
    setMessages([{
      id: 'init',
      role: 'model',
      content: "Hello! I'm your AI assistant. Configure me in settings to switch between Cloud (Gemini) or Local (Ollama) models.",
      timestamp: new Date()
    }]);
  }, []);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsgText = input;
    setInput(''); // Clear immediately
    setIsLoading(true);

    const newUserMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: userMsgText,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, newUserMsg]);

    try {
      const responseText = await sendMessageToAI(messages, userMsgText, settings);

      const newBotMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: responseText,
        timestamp: new Date()
      };

      setMessages(prev => [...prev, newBotMsg]);
    } catch (error) {
      console.error(error);
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'model',
        content: `Error (${settings.aiProvider}): Connection failed. Please check your settings or network.`,
        timestamp: new Date()
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  // Helper to format time like "15:30"
  const formatTime = (date: Date) => {
    return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false });
  };

  return (
    <div className="flex items-center justify-center h-screen w-full bg-cover bg-center font-sans" style={{ backgroundImage: 'url("https://images.unsplash.com/photo-1477346611705-65d1883cee1e?q=80&w=2070&auto=format&fit=crop")' }}>

      <SettingsModal 
        isOpen={isSettingsOpen}
        onClose={() => setIsSettingsOpen(false)}
        settings={settings}
        onSave={setSettings}
      />

      {/* Main Window Container */}
      <div className="flex flex-col w-[800px] h-[800px] max-h-[90vh] bg-[#f5f5f5] rounded-lg shadow-2xl overflow-hidden relative">

        {/* Chat Header */}
        <div className="h-[60px] border-b border-[#e7e7e7] flex items-center justify-between px-6 bg-[#f5f5f5] flex-shrink-0 z-10">
          <div className="flex items-center gap-3">
             <div className="flex flex-col">
               <div className="font-medium text-lg text-black">{settings.botNickname}</div>
               <div className="text-[10px] text-gray-500 uppercase tracking-wide">
                 {settings.aiProvider === 'ollama' ? `Local: ${settings.ollamaModel}` : 'Cloud: Gemini'}
               </div>
             </div>
          </div>
          <button 
            onClick={() => setIsSettingsOpen(true)}
            className="text-black/60 hover:text-black transition-colors p-2 hover:bg-gray-200 rounded-md"
            title="Settings"
          >
             <MoreHorizontal size={20} />
          </button>
        </div>

        {/* Messages Area */}
        <div className="flex-1 overflow-y-auto p-6 space-y-2 bg-[#f5f5f5]">
          {messages.map((msg, index) => {
             // Logic to show timestamp
             const showTime = index === 0 || (new Date(msg.timestamp).getTime() - new Date(messages[index-1].timestamp).getTime() > 60000);
             return (
               <React.Fragment key={msg.id}>
                 {showTime && (
                   <div className="flex justify-center my-4">
                     <span className="text-xs text-gray-400 bg-gray-200/50 px-2 py-0.5 rounded">
                       {formatTime(new Date(msg.timestamp))}
                     </span>
                   </div>
                 )}
                 <ChatBubble 
                   message={msg} 
                   userAvatar={settings.userAvatar}
                   botAvatar={settings.botAvatar}
                 />
               </React.Fragment>
             );
          })}
          {isLoading && (
            <div className="flex items-center gap-2 ml-4 mb-4 mt-2">
               <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce"></div>
               <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce delay-75"></div>
               <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce delay-150"></div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>

        {/* Input Area */}
        <div className="h-[160px] border-t border-[#e7e7e7] bg-[#f5f5f5] flex flex-col flex-shrink-0">

          {/* Toolbar */}
          <div className="h-10 px-4 flex items-center gap-4 text-gray-600">
            <button className="hover:text-black transition-colors"><Smile size={20} /></button>
            <button className="hover:text-black transition-colors"><Folder size={20} /></button>
            <button className="hover:text-black transition-colors"><Paperclip size={20} /></button>
          </div>

          {/* Textarea */}
          <textarea
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={handleKeyDown}
            className="flex-1 bg-transparent px-5 py-2 resize-none text-lg text-black placeholder-gray-400 focus:outline-none"
            placeholder={settings.aiProvider === 'ollama' ? "Message local model..." : "Message Gemini..."}
          />

          {/* Footer / Send Button */}
          <div className="h-12 px-5 flex items-center justify-end">
            <span className="text-xs text-gray-400 mr-4">Press Enter to send</span>
            <button 
              onClick={handleSend}
              disabled={!input.trim() || isLoading}
              className={`px-6 py-1.5 text-sm rounded-sm transition-colors border ${
                 input.trim() 
                 ? 'bg-[#e9e9e9] text-[#07c160] border-[#e9e9e9] hover:bg-[#d2d2d2]' 
                 : 'bg-[#e9e9e9] text-gray-400 border-[#e9e9e9] cursor-default'
              }`}
            >
              Send
            </button>
          </div>
        </div>

      </div>
    </div>
  );
};

export default App;

import { GoogleGenAI } from "@google/genai";
import { Message, AppSettings } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Type definitions for Chrome's experimental built-in AI
declare global {
  interface Window {
    ai?: {
      languageModel?: {
        capabilities: () => Promise<{ available: 'readily' | 'after-download' | 'no' }>;
        create: (options?: any) => Promise<{
          prompt: (input: string) => Promise<string>;
          promptStreaming?: (input: string) => AsyncIterable<string>;
        }>;
      };
    };
  }
}

/**
 * Tries to generate a response using Chrome's built-in local AI (Gemini Nano).
 */
const generateLocalBrowserResponse = async (text: string): Promise<string | null> => {
  try {
    if (!window.ai?.languageModel) {
      return null;
    }

    const capabilities = await window.ai.languageModel.capabilities();
    if (capabilities.available === 'no') {
      return null;
    }

    const session = await window.ai.languageModel.create({
      systemPrompt: "You are a helpful assistant. Keep answers concise."
    });

    const result = await session.prompt(text);
    return `[Chrome Built-in AI] ${result}`;
  } catch (error) {
    console.warn("Failed to use Chrome local AI:", error);
    return null;
  }
};

/**
 * Sends a message to a local Ollama instance.
 */
const sendMessageToOllama = async (
  history: Message[], 
  newMessage: string,
  settings: AppSettings
): Promise<string> => {
  // Convert history to Ollama format (user/assistant)
  // We take the last few messages to keep context without exceeding context windows too fast
  const messages = history.slice(-10).map(msg => ({
    role: msg.role === 'model' ? 'assistant' : 'user',
    content: msg.content
  }));

  // Add the new message
  messages.push({ role: 'user', content: newMessage });

  const payload = {
    model: settings.ollamaModel || 'qwen2.5:7b',
    messages: messages,
    stream: false, // For simplicity in this implementation, we wait for full response
    options: {
      temperature: 0.7
    }
  };

  try {
    const response = await fetch(`${settings.ollamaBaseUrl.replace(/\/$/, '')}/api/chat`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(payload)
    });

    if (!response.ok) {
      throw new Error(`Ollama Error: ${response.statusText}`);
    }

    const data = await response.json();
    return data.message.content;

  } catch (error) {
    console.error("Ollama connection failed", error);
    throw new Error("Could not connect to Ollama. Make sure it's running and OLLAMA_ORIGINS='*' is set.");
  }
};

/**
 * Sends a message to Google Gemini.
 */
const sendMessageToGeminiCloud = async (
  history: Message[], 
  newMessage: string
): Promise<string> => {
  const chatHistory = history.slice(-15).map(msg => ({
    role: msg.role,
    parts: [{ text: msg.content }],
  }));

  const chat = ai.chats.create({
    model: 'gemini-2.5-flash',
    history: chatHistory,
    config: {
      systemInstruction: "You are a friendly friend chatting on a messaging app. Keep your responses casual, helpful, and concise. Use emojis occasionally.",
    },
  });

  const result = await chat.sendMessage({ message: newMessage });
  return result.text || "";
};

/**
 * Main Orchestrator Function
 */
export const sendMessageToAI = async (
  history: Message[], 
  newMessage: string,
  settings: AppSettings
): Promise<string> => {

  // 1. If Ollama is selected
  if (settings.aiProvider === 'ollama') {
    return await sendMessageToOllama(history, newMessage, settings);
  }

  // 2. If Gemini is selected
  // Check offline status first
  if (!navigator.onLine) {
    console.log("App is offline.");
    const localResponse = await generateLocalBrowserResponse(newMessage);
    if (localResponse) return localResponse;
    return "Network Error: You are offline and no local browser model is available.";
  }

  try {
    return await sendMessageToGeminiCloud(history, newMessage);
  } catch (error) {
    console.warn("Gemini Cloud API Error:", error);

    // Fallback to browser built-in AI if cloud fails
    const localResponse = await generateLocalBrowserResponse(newMessage);
    if (localResponse) return localResponse;

    throw error;
  }
};

export interface Message {
  id: string;
  role: 'user' | 'model';
  content: string;
  timestamp: Date;
}

export interface LogEntry {
  id: string;
  timestamp: string;
  level: string;
  message: string;
}

export type AIProvider = 'ollama' | 'chrome_builtin';

export interface AppSettings {
  userAvatar: string;
  botNickname: string;
  botAvatar: string;
  aiProvider: AIProvider;
  ollamaModel: string;
  ollamaBaseUrl: string;
}

